// Gate weights for the native exploration mixture (CLNA_EPS, nnrec.cpp clna_explore). Generated by
// tools/rl_env_1104/native/gate_export.py for a trained gate; this default (all-zero weights, bias = logit(CLNA_EPS))
// reproduces the fixed-epsilon policy exactly. Gate: alpha(h) = sigmoid(kBias + sum_i kW[i] * x_i) over kN inputs:
//   0 q(reference)  1 max q  2 entropy(q) / log(#candidates)  3 round / 2000  4 gems / 100  5 hp / max_hp
//   6 min(visible enemies, 6) / 6  7 #candidates / 14
#pragma once
#include <cmath>
namespace clna_gate {
inline constexpr int kN = 8;
inline constexpr char kVersion[] = "clna-gate-v1-default";
inline constexpr float kW[kN] = { 0, 0, 0, 0, 0, 0, 0, 0 };
inline const double kBias = std::log(static_cast<double>(CLNA_EPS) / (1.0 - static_cast<double>(CLNA_EPS)));
}  // namespace clna_gate
